/** Each point's weights along `chain` (bones by index), a row of every bone's per point, before normalising. */
const chainWeights = <B extends string>(
  specs: ReadonlyArray<Spec<B>>,
  rest: Float64Array,
  axes: ReadonlyArray<Pt>,
  chain: ReadonlyArray<number>,
  blend: number | undefined,
  pts: ReadonlyArray<Pt>,
): Float64Array => {
  const n = specs.length;
  const out = new Float64Array(pts.length * n);
  const joints = chain
    .slice(0, -1)
    .map((j, k) => jointOf(specs, rest, axes, j, chain[k + 1] ?? j, blend));
  pts.forEach(([x, y], i) => {
    // Bone k holds from joint k − 1's step to joint k's: the steps telescope to 1.
    const steps = joints.map(({ at, n: [nx, ny], half }) =>
      smoothstep(-half, half, (x - at[0]) * nx + (y - at[1]) * ny),
    );
    chain.forEach((bone, k) => {
      const w = (k === 0 ? 1 : (steps[k - 1] ?? 0)) - (steps[k] ?? 0);
      out[i * n + bone] = (out[i * n + bone] ?? 0) + Math.max(0, w);
    });
  });
  return out;
}

/** Each point's weights by the drawing's own `weigh`, a row of every bone's per point, before normalising. */
const ownWeights = <B extends string>(
  names: ReadonlyArray<B>,
  weigh: (p: Pt) => ByBone<B>,
  pts: ReadonlyArray<Pt>,
): Float64Array => {
  const n = names.length;
  const out = new Float64Array(pts.length * n);
  pts.forEach((p, i) => {
    const w = weigh(p);
    names.forEach((name, b) => {
      out[i * n + b] = Math.max(0, w[name] ?? 0);
    });
  });
  return out;
}

/** Skin `spec` bound to bones at `rest`. */
const bind = <B extends string, S extends string>(
  specs: ReadonlyArray<Spec<B>>,
  rest: Float64Array,
  axes: ReadonlyArray<Pt>,
  spec: SkinSpec<S>,
): Bound => {
  const n = specs.length;
  const names: ReadonlyArray<string> = specs.map((b) => b.name);
  const closed = spec.options.closed ?? true;
  const pts = restPath(spec.path, closed, spec.options.spacing);
  const weights = spec.weights;
  const raw =
    'chain' in weights
      ? chainWeights(
          specs,
          rest,
          axes,
          weights.chain.map((b) => names.indexOf(b)).filter((i) => i >= 0),
          weights.blend,
          pts,
        )
      : ownWeights(names, weights.weigh, pts);
  return {
    pts,
    w: normalise(raw, n),
    local: localsOf(rest, n, pts),
    closed,
    smooth: spec.options.smooth,
  };
}

/** `verse` set in `style` with its first baseline at (x, y): its lines and the phrase's word boxes. */
const verseLayout = (
  ctx: CanvasRenderingContext2D,
  verse: Verse,
  style: VerseStyle,
  x: number,
  y: number,
): VerseSet => {
  const words = verse.text.split(/\s+/).filter((s) => s.length > 0);
  const phrase = verse.phrase.split(/\s+/).filter((s) => s.length > 0);
  const first = Option.getOrElse(phraseAt(words, phrase), () => -1);
  const s = style.type;
  const tall = (s.leading ?? 1.3) * s.size;
  const space = measure(ctx, ' ', s);
  const lines: Array<{ text: string; y: number }> = [];
  const boxes: Box[] = [];
  let line = '';
  let lx = 0;
  let row = 0;
  for (const [i, word] of words.entries()) {
    const ww = measure(ctx, word, s);
    if (line.length > 0 && lx + space + ww > style.width) {
      lines.push({ text: line, y: y + row * tall });
      line = '';
      lx = 0;
      row++;
    }
    const at = line.length === 0 ? 0 : lx + space;
    if (first >= 0 && i >= first && i < first + phrase.length)
      boxes.push({ x: x + at, y: y + row * tall - s.size * 0.95, w: ww, h: s.size * 1.25 });
    line = line.length === 0 ? word : `${line} ${word}`;
    lx = at + ww;
  }
  if (line.length > 0) lines.push({ text: line, y: y + row * tall });
  return { lines, phrase: boxes };
}

/**
 * A montage as the review lists it, from its manifest: its sets (in clip
 * order) as render choice points at no address of a film, each variant it
 * names with its tag and verdict as its lines, its images in manifest
 * order, and its videos and docs newest first. Missing files are left out
 * and each image path appears once. Pure.
 */
export const montageFolder = (parts: FolderParts<ReviewManifest>): ReviewFolder => {
  const manifest = parts.record;
  const sets = Object.entries(manifest.sets)
    .toSorted(([a], [b]) => a.localeCompare(b))
    .flatMap(([clip, set]): ReadonlyArray<ChoicePoint> => {
      const variants = variantIds(set).flatMap((id) => {
        const meta = Rec.get(set.variants, id);
        return Option.toArray(
          Option.map(videoOf(parts, variantNames(clip, id, set)), (video): ChoiceVariant => ({
            id,
            label: Option.getOrElse(
              Option.flatMap(meta, (v) => v.label),
              () => id,
            ),
            lines: [
              ...Option.toArray(Option.flatMap(meta, (v) => v.tag)),
              ...Option.toArray(Option.flatMap(meta, (v) => v.verdict)),
            ],
            state: 'current',
            staleBy: Option.none(),
            picked: false,
            verbs: [],
            media: { _tag: 'Seen', video },
            key: video.ref,
            approval: 'none',
            comments: [],
            notes: Option.map(
              Option.flatMap(
                Option.flatMap(meta, (v) => v.notes),
                parts.look,
              ),
              fileOf,
            ),
          })),
        );
      });
      if (variants.length === 0) return [];
      return [
        {
          ...pointHead({ _tag: 'Montage', clip }),
          address: Option.none(),
          title: Option.getOrElse(set.title, () => clip),
          lines: [],
          start: set.start,
          moments: set.moments,
          marks: [],
          knob: Option.none(),
          variants,
        },
      ];
    });
  const videos = found(parts, manifest.videos).filter((f) => f.size <= parts.maxVideo);
  return {
    ref: parts.ref,
    title: manifest.title,
    blurb: manifest.blurb,
    mtime: newestMtime(found(parts, namesInMontage(manifest))),
    sets,
    videos: Arr.sort(videos, newestFirst).map((f) => ({ ...fileOf(f), phone: parts.phone(f) })),
    images: uniqueFiles(found(parts, manifest.images)).map(fileOf),
    docs: newestFiles(found(parts, manifest.docs)),
    downloads: uniqueFiles(found(parts, manifest.downloads)).map(fileOf),
    ...Option.match(manifest.production, {
      onNone: () => ({}),
      onSome: (production) => ({
        production,
        ...Option.match(manifest.version, {
          onNone: () => ({}),
          onSome: (version) => ({ version }),
        }),
        ...Option.match(manifest.published, {
          onNone: () => ({}),
          onSome: (published) => ({ published }),
        }),
      }),
    }),
  };
}

const publishSet = Effect.fn('LabMcp.publishSet')(function* (
  name: string,
  files: ReadonlyArray<typeof SetFile.Type>,
  patch: typeof ManifestPatch.Type,
) {
  const dir = path.join(out, name);
  const ref = yield* Effect.fromOption(refOf(review.roots, dir, path), () =>
    LabRefused.make({ reason: `the lab's out/ (${out}) is under none of its review roots` }),
  );
  // Every file checked before anything is written.
  const copies = yield* Effect.forEach(files, (f) =>
    Effect.gen(function* () {
      if (!path.isAbsolute(f.from))
        return yield* LabRefused.make({
          reason: `${f.from}: name the file by its absolute path`,
        });
      const info = yield* refused(fs.stat(f.from));
      if (info.type !== 'File')
        return yield* LabRefused.make({ reason: `${f.from} is not a file` });
      const rel = f.to ?? path.basename(f.from);
      if (!SET_FILE.test(rel))
        return yield* LabRefused.make({
          reason: `${rel}: a set carries images, videos, sound, docs and captions`,
        });
      const to = yield* Effect.fromOption(inside(path, dir, rel), () =>
        LabRefused.make({ reason: `${rel} is not a place in the set's folder` }),
      );
      return { from: f.from, to };
    }),
  );
  const written = yield* refused(
    store.transact(manifestAt(dir), (current) =>
      Effect.gen(function* () {
        for (const copy of copies) {
          yield* fs.makeDirectory(path.dirname(copy.to), { recursive: true });
          // Copied whole: the review never lists half a video.
          yield* writeWholeWith(
            fs,
            copy.to,
            (partial) => fs.copyFile(copy.from, partial),
            (partial) => fs.rename(partial, copy.to),
          );
        }
        const next = { ...current, ...patch };
        const manifest = yield* Schema.decodeUnknownEffect(ReviewManifest)(next).pipe(
          Effect.mapError((e) => LabRefused.make({ reason: `review.json: ${e.message}` })),
        );
        const named = [
          ...manifest.docs,
          ...manifest.images,
          ...manifest.videos,
          ...manifest.downloads,
        ];
        const missing = yield* Effect.filter(named, (file) =>
          Option.match(inside(path, dir, file), {
            onNone: () => Effect.succeed(true),
            onSome: (at) => Effect.map(fs.exists(at), (there) => !there),
          }),
        );
        if (missing.length > 0)
          return yield* LabRefused.make({
            reason: `review.json names what the folder lacks: ${missing.join(', ')}`,
          });
        return [manifest, next] as const;
      }),
    ),
  );
  yield* Effect.log(`lab.mcp.publish set=${ref} files=${copies.length}`);
  return { set: ref, link: linkOf(pageHref.folder(ref)), dir, manifest: written };
})

/** The new-side lines each file's hunks add or change, read from `git diff --unified=0`. */
const changedLines = (diff: string): ReadonlyMap<string, ReadonlySet<number>> => {
  const changed = new Map<string, Set<number>>();
  let lines = new Set<number>();
  for (const row of diff.split('\n')) {
    if (row.startsWith('+++ ')) {
      lines = new Set<number>();
      if (row.startsWith('+++ b/')) changed.set(row.slice('+++ b/'.length), lines);
      continue;
    }
    const hunk = HUNK.exec(row);
    if (!hunk) continue;
    const start = Number(hunk[1]);
    const count = Number(hunk[2] ?? '1');
    for (let line = start; line < start + count; line++) lines.add(line);
  }
  return changed;
}

const hold = Effect.fn('BeatEdits.hold')(function* (ask: HoldAsk) {
  const film = yield* filmNamed(ask.film).pipe(Effect.provideContext(films));
  const target = holdTarget(ask.beat, ask.edge);
  const { timeline, file } = yield* versionOf(film, ask.version, target);
  const clip = yield* Effect.fromOption(
    Option.fromUndefinedOr(scriptClips(timeline).find((c) => c.beat === ask.beat)),
  ).pipe(
    Effect.mapError(() =>
      SourceRefused.make({
        file: SCRIPT_FILE,
        target,
        reason: `the script has no beat "${ask.beat}"`,
      }),
    ),
  );
  const now = onTheMs(clip.hold[ask.edge]);
  const value = heldWithin(ask.edge, ask.seconds, now);
  const as = holdWritten(ask.edge, value);
  // A hold laid out where it is asked, and not declared, is already so: nothing to write.
  const already = value === now && !clip.hold.declared.includes(ask.edge);
  return yield* written(
    film,
    timeline,
    {
      file,
      beat: ask.beat,
      target,
      said: heldWords(ask.beat, ask.edge, now, value),
      already: heldAlready(ask.beat, ask.edge, value),
      by: ask.by,
    },
    (source) =>
      Bool.match(already, {
        onTrue: () => Result.succeed(source),
        onFalse: () => editHold(source, ask.beat, ask.edge, as),
      }),
    (after) =>
      Bool.match(already, {
        onTrue: () => Result.succeed<ReadonlyArray<string>>([]),
        onFalse: () => holdMissed(after, ask.beat, ask.edge, as),
      }),
  );
})

/**
 * Lists all notes in the default Notes account.
 * @returns An Effect that resolves with an array of NoteListItem objects.
 * @throws NoteOperationError if the AppleScript execution or parsing fails.
 */
export const listNotes = Effect.fn('listNotes')(function* () {
  yield* Effect.log('🔄 Fetching list of notes...');
  const script = `
    set noteList to {}
    tell application "Notes"
      set allNotes to every note
      set noteCount to count of allNotes -- Get total count
      set counter to 0
      repeat with i from 1 to noteCount
        if counter is 20 then exit repeat -- Stop after 20
        set aNote to item i of allNotes

        set noteId to id of aNote
        set noteName to name of aNote
        set noteCreationDate to creation date of aNote as string
        set noteModificationDate to modification date of aNote as string
        set end of noteList to {noteId:noteId, noteName:noteName, creationDate:noteCreationDate, modificationDate:noteModificationDate}
        set counter to counter + 1 -- Increment counter
      end repeat
    end tell

    -- Format the output as a simple, parseable string (e.g., ID|Name|Created|Modified newline)
    set output to ""
    repeat with noteProps in noteList
      set output to output & noteProps's noteId & "|" & noteProps's noteName & "|" & noteProps's creationDate & "|" & noteProps's modificationDate & "\n"
    end repeat
    return output
  `;

  const rawOutput = yield* execCommand(script).pipe(
    Effect.mapError(
      (error) =>
        new NoteOperationError({
          message: 'Failed to execute listNotes AppleScript',
          cause: error,
          script,
        }),
    ),
  );

  yield* Effect.log('📊 Parsing note list...');
  const malformed: string[] = [];
  const notes: NoteListItem[] = [];
  for (const line of rawOutput.split('\n')) {
    if (line.trim() === '') continue; // Remove empty lines
    const parts = line.split('|'); // Split by the delimiter
    if (parts.length !== 4) {
      // Handle potential parsing errors or unexpected format
      malformed.push(line);
      continue;
    }
    notes.push({
      id: parts[0] ?? '',
      name: parts[1] ?? '', // Names might contain special characters, handled by script?
      creationDate: parts[2] ?? '',
      modificationDate: parts[3] ?? '',
    });
  }

  if (malformed.length > 0) {
    yield* Effect.logWarning(
      `Skipped ${malformed.length} malformed lines: ${malformed.join('; ')}`,
    );
  }

  yield* Effect.log(`✅ Found ${notes.length} notes.`);
  return notes;
})

const versesFor = (reference: string) =>
  Effect.gen(function* () {
    const parsed = parseBibleQuery(reference);
    if (parsed._tag === 'search') return [];
    return yield* versesForBibleQuery(parsed).pipe(Effect.orElseSucceed(() => []));
  })

const mergedCatalog = (
  sources: readonly WritingsAssetSourceService[],
): Effect.Effect<readonly Publication[], CorpusSourceUnavailableError> =>
  Effect.gen(function* () {
    const publications = new Map<PublicationId, Publication>();
    let unavailable = Option.none<CorpusSourceUnavailableError>();
    for (const source of sources) {
      const result = yield* Effect.result(source.catalog);
      if (Result.isFailure(result)) {
        unavailable = Option.some(result.failure);
        continue;
      }
      for (const publication of result.success) {
        if (!publications.has(publication.id)) publications.set(publication.id, publication);
      }
    }
    if (publications.size > 0) return [...publications.values()];
    if (Option.isSome(unavailable)) return yield* unavailable.value;
    return [];
  })

const expandParsed = (
  parsed: ReturnType<typeof parseBibleQuery>,
): readonly { bibleBook: number; bibleChapter: number; bibleVerse: Option.Option<number> }[] => {
  switch (parsed._tag) {
    case 'single': {
      return [
        {
          bibleBook: parsed.ref.book,
          bibleChapter: parsed.ref.chapter,
          bibleVerse: Option.some(parsed.ref.verse),
        },
      ];
    }
    case 'chapter':
      return [
        { bibleBook: parsed.ref.book, bibleChapter: parsed.ref.chapter, bibleVerse: Option.none() },
      ];
    case 'verseRange': {
      const rows: {
        bibleBook: number;
        bibleChapter: number;
        bibleVerse: Option.Option<number>;
      }[] = [];
      for (let v = parsed.ref.start.verse; v <= parsed.ref.end.verse; v++) {
        rows.push({
          bibleBook: parsed.ref.start.book,
          bibleChapter: parsed.ref.start.chapter,
          bibleVerse: Option.some(v),
        });
      }
      return rows;
    }
    case 'chapterRange':
    case 'fullBook':
    case 'search':
      return [];
  }
}

/** Compiles a hymn from its text and its MIDI file. */
export const compile = (source: Source): Effect.Effect<Hymn, Midi.MidiParseError> =>
  Effect.gen(function* () {
    const stanzas = source.verses
      .filter((verse) => verse.id >= 0)
      .toSorted((a, b) => a.id - b.id)
      .map((verse) => linesOf(verse.text));
    // The refrain: the negative id nearest zero (a few texts keep more than one).
    const chorus = source.verses.filter((verse) => verse.id < 0).toSorted((a, b) => b.id - a.id)[0];
    const refrain = chorus === undefined ? undefined : linesOf(chorus.text);
    const score = Score.fromMidi(yield* Midi.parse(source.midi), stanzas.length);
    const head = {
      version: 1,
      book: source.book,
      number: source.number,
      title: source.title,
      key: score.key,
      meter: score.meter,
      verses: {
        text: stanzas.length,
        midi: score.verses.spans.length,
        exact: score.verses.exact,
      },
    } as const;
    if (!Arr.isArrayNonEmpty(stanzas)) {
      return yield* Effect.die(new Error(`hymn ${source.number} has no stanza`));
    }
    if (source.held !== undefined) {
      const plain: Mutable<Hymn> = { ...head, stanzas: Arr.map(stanzas, held) };
      if (refrain !== undefined) plain.refrain = held(refrain);
      return plain;
    }
    const tail = refrain ?? [];
    const laid = Arr.map(stanzas, (lines, n) => lay(score, n, [...lines, ...tail]));
    const parts = Arr.map(laid, (one, n) => {
      const lines = stanzas[n] ?? [];
      return partOf(one, lines, 0, lines.length);
    });
    const first = laid[0];
    const firstLines = stanzas[0].length;
    const hymn: Mutable<Hymn> = { ...head, stanzas: parts };
    if (refrain !== undefined) {
      hymn.refrain = partOf(first, refrain, firstLines, firstLines + refrain.length);
    }
    return hymn;
  })

const list = (json: boolean) =>
  Effect.gen(function* () {
    const outputDir = getOutputsPath(config.outputDir);
    const files = yield* fs
      .readDirectory(outputDir)
      .pipe(Effect.orElseSucceed(() => [] as string[]));

    const mdFiles = files.filter((f) => f.endsWith('.md'));
    const sorted = sortFiles(mdFiles, config.sortStrategy);
    const filePaths = sorted.map((f) => path.join(outputDir, f));

    if (json) {
      const jsonOutput = yield* encodeJson(filePaths);
      yield* Effect.log(jsonOutput);
    } else if (sorted.length === 0) {
      yield* Effect.log(`No ${config.displayName.toLowerCase()}s found.`);
    } else {
      yield* Effect.log(`${config.displayName}s:`);
      for (const file of sorted) {
        yield* Effect.log(`  ${file}`);
      }
    }
  })

/** `verse` set in `style` with its first baseline at (x, y): its lines and the phrase's word boxes. */
const verseLayout = (
  ctx: CanvasRenderingContext2D,
  verse: Verse,
  style: VerseStyle,
  x: number,
  y: number,
): VerseSet => {
  const words = verse.text.split(/\s+/).filter((s) => s.length > 0);
  const phrase = verse.phrase.split(/\s+/).filter((s) => s.length > 0);
  // A phrase that is not a run of the verse's words (a typo, other punctuation) would
  // highlight nothing and flood from nowhere: Scripture is set verbatim, so it stops here.
  const found = Option.filter(phraseAt(words, phrase), () => phrase.length > 0);
  if (Option.isNone(found))
    throw new Error(
      `verse: the phrase "${verse.phrase}" is no run of the words of "${verse.text}" (set both verbatim)`,
    );
  const first = found.value;
  const s = style.type;
  const tall = (s.leading ?? 1.3) * s.size;
  const space = measure(ctx, ' ', s);
  const lines: Array<{ text: string; y: number }> = [];
  const boxes: Box[] = [];
  let line = '';
  let lx = 0;
  let row = 0;
  for (const [i, word] of words.entries()) {
    const ww = measure(ctx, word, s);
    if (line.length > 0 && lx + space + ww > style.width) {
      lines.push({ text: line, y: y + row * tall });
      line = '';
      lx = 0;
      row++;
    }
    const at = line.length === 0 ? 0 : lx + space;
    if (i >= first && i < first + phrase.length)
      boxes.push({ x: x + at, y: y + row * tall - s.size * 0.95, w: ww, h: s.size * 1.25 });
    line = line.length === 0 ? word : `${line} ${word}`;
    lx = at + ww;
  }
  if (line.length > 0) lines.push({ text: line, y: y + row * tall });
  return { lines, phrase: boxes };
}

// A write drops the review's index (`written`), refused or not, so its next read sees the folder as it is.
const publishSet = Effect.fn('LabMcp.publishSet')(function* (
  name: string,
  files: ReadonlyArray<typeof SetFile.Type>,
  patch: typeof ManifestPatch.Type,
) {
  const dir = path.join(out, name);
  const ref = yield* Effect.fromOption(refOf(review.roots, dir, path), () =>
    LabRefused.make({ reason: `the lab's out/ (${out}) is under none of its review roots` }),
  );
  // A project folder is a film's renders: the review reads it by its catalogue, never as a montage.
  const elsewhere =
    'publish the set under another name, and record a render there with `record_render`';
  if ((yield* folder.names).includes(name))
    return yield* LabRefused.make({
      reason: `${name} is film ${name}'s project folder, where its renders are recorded: ${elsewhere}`,
    });
  if (yield* fs.exists(path.join(dir, CATALOGUE_FILE)).pipe(Effect.orElseSucceed(() => false)))
    return yield* LabRefused.make({
      reason: `${name} is a project folder (its ${CATALOGUE_FILE}): ${elsewhere}`,
    });
  // Every copy checked before anything is written.
  const copies = yield* Effect.forEach(files, (f) =>
    Effect.gen(function* () {
      if (!path.isAbsolute(f.from))
        return yield* LabRefused.make({
          reason: `${f.from}: name the file by its absolute path`,
        });
      const info = yield* refused(fs.stat(f.from));
      if (info.type !== 'File')
        return yield* LabRefused.make({ reason: `${f.from} is not a file` });
      const rel = f.to ?? path.basename(f.from);
      if (!SET_FILE.test(rel))
        return yield* LabRefused.make({
          reason: `${rel}: a set carries images, videos, sound, docs and captions`,
        });
      const to = yield* Effect.fromOption(inside(path, dir, rel), () =>
        LabRefused.make({ reason: `${rel} is not a place in the set's folder` }),
      );
      return { from: f.from, to };
    }),
  );
  // The manifest and every name in it judged before a file is copied: a refused publish writes nothing.
  const written = yield* refused(
    store.transact(manifestAt(dir), (current) =>
      Effect.gen(function* () {
        const next = { ...current, ...patch };
        const manifest = yield* Schema.decodeUnknownEffect(ReviewManifest)(next).pipe(
          Effect.mapError((e) => LabRefused.make({ reason: `review.json: ${e.message}` })),
        );
        // Every file it names as the review finds it once the copies land (a variant with no `file`, by either copy).
        const there = (name: string) =>
          Option.match(inside(path, dir, name), {
            onNone: () => Effect.succeed(false),
            onSome: (at) =>
              Effect.map(fs.exists(at), (found) => found || copies.some((c) => c.to === at)),
          });
        const missing = yield* Effect.filter(filesInMontage(manifest), (names) =>
          Effect.map(Effect.forEach(names, there), (found) => !found.includes(true)),
        );
        if (missing.length > 0)
          return yield* LabRefused.make({
            reason: `review.json names what the folder lacks: ${missing.map((names) => names.join(' or ')).join(', ')}`,
          });
        for (const copy of copies) {
          yield* fs.makeDirectory(path.dirname(copy.to), { recursive: true });
          // Copied whole: the review never lists half a video.
          yield* writeWholeWith(
            fs,
            copy.to,
            (partial) => fs.copyFile(copy.from, partial),
            (partial) => fs.rename(partial, copy.to),
          );
        }
        return [manifest, next] as const;
      }),
    ),
  );
  yield* Effect.log(`lab.mcp.publish set=${ref} files=${copies.length}`);
  return {
    set: ref,
    links: linksOf(pageHref.folder(ref)),
    dir,
    manifest: written,
    files: yield* filesOf(ref, dir, written),
  };
}, Effect.ensuring(review.written))

const hold = Effect.fn('BeatEdits.hold')(function* (ask: HoldAsk) {
  const film = yield* filmNamed(ask.film).pipe(Effect.provideContext(films));
  const target = holdTarget(ask.beat, ask.edge);
  const { timeline, file } = yield* versionOf(film, ask.version, target);
  const clip = yield* Effect.fromOption(
    Option.fromUndefinedOr(scriptClips(timeline).find((c) => c.beat === ask.beat)),
  ).pipe(
    Effect.mapError(() =>
      SourceRefused.make({
        file: SCRIPT_FILE,
        target,
        reason: `the script has no beat "${ask.beat}"`,
      }),
    ),
  );
  const now = onTheMs(clip.hold[ask.edge]);
  const value = heldWithin(ask.edge, ask.seconds, now);
  yield* Option.match(holdUnchanged(clip, ask.edge, value), {
    onNone: () => Effect.void,
    onSome: (reason) => HoldUnchanged.make({ beat: ask.beat, edge: ask.edge, reason }),
  });
  const as = holdWritten(ask.edge, value);
  // A hold laid out where it is asked, and not declared, is already so: nothing to write.
  const already = value === now && !clip.hold.declared.includes(ask.edge);
  return yield* written(
    film,
    timeline,
    {
      file,
      beat: ask.beat,
      target,
      said: heldWords(ask.beat, ask.edge, now, value),
      already: heldAlready(ask.beat, ask.edge, value),
      by: ask.by,
    },
    (source) =>
      Bool.match(already, {
        onTrue: () => Result.succeed(source),
        onFalse: () => editHold(source, ask.beat, ask.edge, as),
      }),
    (after) =>
      Bool.match(already, {
        onTrue: () => Result.succeed<ReadonlyArray<string>>([]),
        onFalse: () => holdMissed(after, ask.beat, ask.edge, as),
      }),
  );
