/**
 * Each point's weights by the drawing's own `weigh`, a row of every bone's
 * per point, before normalising. A weight that is not a finite number is 0,
 * and handed to `refuse` with its bone.
 */
const ownWeights = (
  names: ReadonlyArray<string>,
  weigh: (p: Pt) => ByBone<string>,
  pts: ReadonlyArray<Pt>,
  refuse: (bone: number, value: number) => void,
): Float64Array => {
  const n = names.length;
  const out = new Float64Array(pts.length * n);
  pts.forEach((p, i) => {
    const w = weigh(p);
    names.forEach((name, b) => {
      const x = w[name] ?? 0;
      if (!Number.isFinite(x)) refuse(b, x);
      out[i * n + b] = Number.isFinite(x) ? Math.max(0, x) : 0;
    });
  });
  return out;
}

/** Skin `spec`'s raw weights on bones at `rest` for its points `pts`, and what it refused. */
const weightsOf = <B extends string, S extends string>(
  specs: ReadonlyArray<Spec<B>>,
  rest: Float64Array,
  axes: ReadonlyArray<Pt>,
  spec: SkinSpec<S>,
  pts: ReadonlyArray<Pt>,
) => {
  const names: ReadonlyArray<string> = specs.map((b) => b.name);
  const weights = spec.weights;
  const rejected: Array<SkinRejected<B, S>> = [];
  if ('chain' in weights) {
    const chain = weights.chain.map((b) => names.indexOf(b)).filter((i) => i >= 0);
    const blend = weights.blend;
    const sound = blend === undefined || Number.isFinite(blend);
    if (!sound) rejected.push({ _tag: 'BlendNotFinite', skin: spec.name, value: blend });
    rejected.push(...unlinked(specs, chain, spec.name));
    const raw = chainWeights(specs, rest, axes, chain, sound ? blend : undefined, pts);
    return { raw, rejected };
  }
  // Each bone's refusals counted, so a falloff's 0/0 is named once, not once a point.
  const refused = new Map<number, { value: number; points: number }>();
  const raw = ownWeights(names, weights.weigh, pts, (b, value) => {
    const seen = refused.get(b);
    refused.set(b, { value: seen?.value ?? value, points: (seen?.points ?? 0) + 1 });
  });
  for (const [b, { value, points }] of refused) {
    const bone = specs[b]?.name;
    if (bone !== undefined)
      rejected.push({ _tag: 'WeightNotFinite', skin: spec.name, bone, value, points });
  }
  return { raw, rejected };
}

/** A chain's links that are not parent → child, named for skin `skin`. */
const unlinked = <B extends string, S extends string>(
  specs: ReadonlyArray<Spec<B>>,
  chain: ReadonlyArray<number>,
  skin: S,
): Array<SkinRejected<B, S>> =>
  chain.slice(1).flatMap((to, k) => {
    const from = chain[k] ?? 0;
    const [a, b] = [specs[from], specs[to]];
    if (a === undefined || b === undefined || b.parent === from) return [];
    return [{ _tag: 'ChainNotLinked', skin, from: a.name, to: b.name } as const];
  })

/** Pose value `x` of `bone`'s `field`, or undefined (rest) with its rejection named when it is not finite. */
const finite = <B extends string>(
  bone: B,
  field: keyof BonePose,
  x: number | undefined,
  rejected: Array<PoseNotFinite<B>>,
): number | undefined => {
  if (x === undefined || Number.isFinite(x)) return x;
  rejected.push({ _tag: 'PoseNotFinite', bone, field, value: x });
  return undefined;
}

/** A frame's values with every non-finite field held at rest and named; the values as given when all are sound. */
const soundValues = <B extends string>(
  names: ReadonlyArray<B>,
  values: PoseValues<B>,
): Sound<B> => {
  const rejected: Array<PoseNotFinite<B>> = [];
  if (names.every((name) => allFinite(values[name] ?? AT_REST))) return { values, rejected };
  const out: { [K in B]?: BonePose } = {};
  for (const name of names) {
    const v = values[name];
    if (v !== undefined) out[name] = finiteBone(name, v, rejected);
  }
  return { values: out, rejected };
}

/**
 * The answer's last fenced `json` block, its findings read one by one on
 * the figures asked about (`figures`, named in any case, kept in the case
 * asked): a finding that does not read, or names no figure asked about, is
 * rejected and said, never taken as none. Fails when there is no block, or
 * it is not `{"findings": [...]}`.
 */
export const findingsOf = (
  answer: string,
  figures: ReadonlyArray<string>,
): Result.Result<CritiqueRead, string> =>
  Option.match(Arr.last([...answer.matchAll(/```json\s*\n([\s\S]*?)\n```/g)]), {
    onNone: () => Result.fail('the answer ends with no ```json block'),
    onSome: (block) =>
      Result.mapBoth(decodeAnswer(block[1] ?? ''), {
        onFailure: (error) => `its json block does not read: ${error.message}`,
        onSuccess: (read) =>
          read.findings.reduce<CritiqueRead>(
            (acc, raw, index) =>
              Result.match(decodeFinding(raw), {
                onFailure: (error) => ({
                  ...acc,
                  rejected: [
                    ...acc.rejected,
                    `finding ${index + 1} does not read: ${error.message}`,
                  ],
                }),
                onSuccess: (finding) =>
                  Option.match(
                    Arr.findFirst(figures, (f) => f.toLowerCase() === finding.figure.toLowerCase()),
                    {
                      onNone: () => ({
                        ...acc,
                        rejected: [
                          ...acc.rejected,
                          `finding ${index + 1} names ${finding.figure}, no figure asked about (${figures.join(', ')})`,
                        ],
                      }),
                      onSome: (figure) => ({
                        ...acc,
                        findings: [...acc.findings, { ...finding, figure }],
                      }),
                    },
                  ),
              }),
            { findings: [], rejected: [] },
          ),
      }),
  })

/** The answer's last fenced `json` block, decoded, or why it cannot be read. */
export const findingsOf = (answer: string): Result.Result<ReadonlyArray<CritiqueFinding>, string> =>
  Option.match(Arr.last([...answer.matchAll(/```json\s*\n([\s\S]*?)\n```/g)]), {
    onNone: () => Result.fail('the answer ends with no ```json block'),
    onSome: (block) =>
      Result.mapBoth(decodeAnswer(block[1] ?? ''), {
        onFailure: (error) => `its json block does not read: ${error.message}`,
        onSuccess: (read) => read.findings,
      }),
  })

/**
 * The text's stanzas in printed order and its refrain. The order is known
 * only when the stanzas' ids are 0, 1, … n - 1 and at most one verse, the
 * refrain, has a negative id, and every verse has a letter; a refrain comes
 * with the order its page sings it in, and an order only with a refrain: any
 * other layout is refused.
 */
const versesOf = (source: Source) => {
  const ids = source.verses.map((verse) => verse.id);
  const stanzas = source.verses.filter((verse) => verse.id >= 0).toSorted((a, b) => a.id - b.id);
  const choruses = source.verses.filter((verse) => verse.id < 0);
  const refuse = (reason: VerseLayoutReason) => Effect.fail(VerseLayoutError.make({ ids, reason }));
  if (!Arr.isArrayNonEmpty(stanzas)) return refuse('no stanza');
  if (stanzas.some((verse, n) => verse.id !== n)) return refuse('stanza ids are not 0, 1, … n - 1');
  if (choruses.length > 1) return refuse('more than one refrain');
  if (source.verses.some((verse) => !/\p{L}/u.test(verse.text)))
    return refuse('a verse has no words');
  const chorus = choruses[0];
  const order = source.order;
  if (chorus === undefined && order !== undefined) return refuse('a refrain order with no refrain');
  if (chorus !== undefined && order === undefined) return refuse('a refrain with no order');
  return Effect.succeed({
    stanzas: Arr.map(stanzas, (verse) => linesOf(verse.text)),
    refrain:
      chorus === undefined || order === undefined
        ? undefined
        : { order, lines: linesOf(chorus.text) },
  });
}

/** `git <args>` run in `root`: what it prints, or `GitFailed` when it exits non-zero. */
const git = (root: string, args: ReadonlyArray<string>) =>
  Effect.scoped(
    Effect.gen(function* () {
      const spawner = yield* ChildProcessSpawner;
      const handle = yield* spawner.spawn(
        ChildProcess.make('git', args, { cwd: root, stderr: 'ignore' }),
      );
      const [out, code] = yield* Effect.all(
        [Stream.mkString(Stream.decodeText(handle.stdout)), handle.exitCode],
        { concurrency: 'unbounded' },
      );
      if (code !== 0)
        return yield* GitFailed.make({
          command: args.find((arg) => !arg.startsWith('-') && !arg.includes('=')) ?? 'git',
          code,
        });
      return out;
    }),
  )

