/**
 * Fetch ±`radius` paragraphs around each of `paraIds`.
 *
 * Returns a map keyed by the anchor's `para_id`. A hit whose anchor is missing
 * — or whose radius is zero — simply maps to empty arrays, so the caller never
 * has to branch on absence.
 *
 * The effect does not fail: context is an enrichment, and a search that
 * returned results should not turn into an error because the surrounding
 * paragraphs could not be read. A failure degrades to no context at all.
 */
export const surroundingParagraphs = (
  paraIds: readonly string[],
  radius: number,
): Effect.Effect<ReadonlyMap<string, Surrounding>, never, SqlClient.SqlClient> =>
  Effect.gen(function* () {
    if (paraIds.length === 0 || radius <= 0) return new Map<string, Surrounding>();

    const sql = yield* SqlClient.SqlClient;

    // `anchors` resolves each hit to its (book_id, puborder); the join then
    // walks the ±radius window off `idx_paragraphs_puborder`. `offset` carries
    // which side of the anchor each row fell on, which is what lets one flat
    // result set be grouped without a second pass over the corpus.
    const rows = yield* sql<WindowRow>`
      with anchors as (
        select para_id as anchor_para_id, book_id, puborder
        from paragraphs
        where para_id in (select value from json_each(${encodeKeys(paraIds)}))
      )
      select
        a.anchor_para_id,
        p.para_id,
        p.refcode_short,
        p.content_text,
        p.is_chapter_heading,
        p.puborder - a.puborder as offset
      from anchors a
      join paragraphs p
        on p.book_id = a.book_id
       and p.puborder between a.puborder - ${radius} and a.puborder + ${radius}
      where p.puborder <> a.puborder
      order by a.anchor_para_id, p.puborder
    `;

    const grouped = new Map<string, Mutable>();
    for (const row of rows) {
      const entry = existingOrNew(grouped, row.anchor_para_id);
      const paragraph: ContextParagraph = {
        refcode: row.refcode_short,
        text: row.content_text,
        url: row.para_id === null ? null : readerUrl(row.para_id),
        isHeading: row.is_chapter_heading === 1,
      };
      if (row.offset < 0) entry.before.push(paragraph);
      else entry.after.push(paragraph);
    }

    const result: Map<string, Surrounding> = grouped;
    return result;
  }).pipe(
    // Enrichment, not a result: a context lookup that fails leaves the hits
    // intact and unadorned rather than failing the search around them.
    Effect.catchCause((cause) =>
      Effect.logWarning('search.context.failed').pipe(
        Effect.annotateLogs({ cause: String(cause) }),
        Effect.as(new Map<string, Surrounding>()),
      ),
    ),
  )

/**
 * One store call, its failure typed and logged with the method and the key
 * it read or wrote (none for a call on the whole store).
 */
const call = <A>(method: string, key: Option.Option<string>, run: () => A) =>
  Effect.try({
    try: run,
    catch: (cause) =>
      Option.match(key, {
        onNone: () => new KeyValueStore.KeyValueStoreError({ message: method, method, cause }),
        onSome: (k) =>
          new KeyValueStore.KeyValueStoreError({
            message: `${method} ${k}`,
            method,
            key: k,
            cause,
          }),
      }),
  }).pipe(
    Effect.tapError((error) =>
      Effect.logWarning('settings.store.failed').pipe(
        Effect.annotateLogs({
          method,
          key: Option.getOrElse(key, () => '*'),
          cause: String(error.cause),
        }),
      ),
    ),
  )

/**
 * Finds a note by its exact title in a specific folder.
 * @param title The exact title to search for.
 * @param folder The folder name to search in.
 * @returns An Effect that resolves with Option<NoteListItem>.
 */
export const findNoteByTitle = Effect.fn('findNoteByTitle')(function* (
  title: string,
  folder: string,
) {
  yield* Effect.log(`🔍 Searching for note "${title}" in folder "${folder}"...`);

  // Escape quotes in title for AppleScript
  const escapedTitle = title.replace(/"/g, '\\"');
  const escapedFolder = folder.replace(/"/g, '\\"');

  const script = `
    tell application "Notes"
      try
        set targetFolder to missing value
        repeat with f in folders
          if name of f is "${escapedFolder}" then
            set targetFolder to f
            exit repeat
          end if
        end repeat
        if targetFolder is missing value then
          return "NOT_FOUND"
        end if
        set matchingNotes to (notes of targetFolder whose name is "${escapedTitle}")
        if (count of matchingNotes) is 0 then
          return "NOT_FOUND"
        end if
        set theNote to item 1 of matchingNotes
        return id of theNote
      on error errMsg number errNum
        return "Error: " & errMsg & " (" & errNum & ")"
      end try
    end tell
  `;

  const result = yield* execCommand(script).pipe(
    Effect.mapError(
      (error) =>
        new NoteOperationError({
          message: `Failed to execute findNoteByTitle AppleScript for "${title}"`,
          cause: error,
          script,
        }),
    ),
  );

  if (result === 'NOT_FOUND') {
    yield* Effect.log(`📭 Note "${title}" not found in folder "${folder}".`);
    return Option.none<string>();
  }

  if (result.startsWith('Error:')) {
    return yield* new NoteOperationError({
      message: `Failed to find note "${title}": ${result}`,
      script,
      scriptOutput: result,
    });
  }

  yield* Effect.log(`✅ Found note "${title}" with ID: ${result}`);
  return Option.some(result);
})

/**
 * Deletes a specific note.
 * @param noteId The ID of the note to delete.
 * @returns An Effect that resolves when the deletion is complete.
 * @throws NoteOperationError if the note is not found or the script fails.
 */
export const deleteNote = Effect.fn('deleteNote')(function* (noteId: string) {
  yield* Effect.log(`🔄 Deleting note ID: ${noteId}...`);
  const script = `
    tell application "Notes"
      try
        delete note id "${noteId}"
        return "Success"
      on error errMsg number errNum
         return "Error: Note not found or deletion failed. " & errMsg & " (" & errNum & ")"
      end try
    end tell
  `;

  const result = yield* execCommand(script).pipe(
    Effect.mapError(
      (error) =>
        new NoteOperationError({
          message: `Failed to execute deleteNote AppleScript for ID ${noteId}`,
          cause: error,
          script,
        }),
    ),
  );

  if (!result.startsWith('Success')) {
    return yield* new NoteOperationError({
      message: `Failed to delete note ID ${noteId}: ${result}`,
      script,
      scriptOutput: result,
    });
  }

  yield* Effect.log(`✅ Note deleted: ${noteId}.`);
})

const checkCitation = (file: string, citation: Citation) =>
  Effect.gen(function* () {
    const problem = (kind: ProblemKind, detail: string): Problem => ({
      file,
      line: citation.line,
      kind,
      detail,
    });

    if (citation._tag === 'scripture') {
      const text = yield* scriptureText(citation.reference);
      if (Option.isNone(text)) return [problem('verse-unresolved', citation.reference)];
      if (!quotationAppearsIn(text.value, citation.quote)) {
        return [problem('verse-mismatch', `${citation.reference}: ${preview(citation.quote)}`)];
      }
      return [];
    }

    const problems: Problem[] = [];
    const [named = ''] = citation.refcodes.toReversed();
    if (isSpliced(citation.quote)) problems.push(problem('witness-spliced', named));
    const words = quotedWordCount(citation.quote);
    if (words > WITNESS_WORD_LIMIT) {
      problems.push(problem('witness-too-long', `${named}: ${words} words`));
    }
    const source = yield* witnessText(citation.refcodes);
    if (Option.isNone(source)) {
      problems.push(
        problem('witness-unresolved', `${citation.kind} ${citation.refcodes[0] ?? ''}`),
      );
    } else if (!quotationAppearsIn(source.value.text, citation.quote)) {
      problems.push(
        problem('witness-mismatch', `${source.value.refcode}: ${preview(citation.quote)}`),
      );
    }
    return problems;
  })

/**
 * Each changed test file redfirst does not run, and why. A rename is read by
 * both paths: one out of the tests (`old.test.ts` to `fixture.ts`) is named by
 * its old path, since its cases are gone.
 */
export const skippedOf = (
  statuses: ReadonlyArray<Change>,
): ReadonlyArray<{ readonly file: string; readonly why: string }> =>
  statuses
    .filter((c) => isTest(c.file) || isTest(c.from))
    .flatMap((c) => {
      if (!isTest(c.file))
        return [
          { file: c.from, why: `renamed to ${c.file}, which is no test: its cases are gone` },
        ];
      if (c.status === 'D') return [{ file: c.file, why: 'deleted: its cases are gone' }];
      if (!['A', 'M', 'R'].includes(c.status))
        return [{ file: c.file, why: `git status ${c.status}: not read` }];
      if (isBrowserTier(c.file)) return [{ file: c.file, why: 'a browser tier: run it by hand' }];
      return [];
    })

/** An answer that is not one of `ok`: its status and S3 error code, as a failure. */
const refused = Effect.fnUntraced(function* (
  call: Pick<Call, 'op' | 'key'>,
  response: HttpClientResponse.HttpClientResponse,
) {
  const body = yield* response.text.pipe(Effect.orElseSucceed(() => ''));
  const code = Option.getOrElse(xmlText(body, 'Code'), () => 'no error code');
  return yield* failed(call.op, call.key, `R2 answered ${response.status} (${code})`);
})

/** The budget's verdict on `run`. */
export const judge = (run: Run): Judged => {
  const timed = run.workspaces
    .flatMap((workspace): ReadonlyArray<Timed> =>
      Option.match(workspace.ms, {
        onNone: () => [],
        onSome: (ms) => [{ ...workspace, ms }],
      }),
    )
    .toSorted((a, b) => b.ms - a.ms);
  const untimed = run.workspaces
    .filter((workspace) => Option.isNone(workspace.ms))
    .toSorted((a, b) => a.name.localeCompare(b.name));
  const measured = quiet(run);
  const passed = timed.filter((workspace) => workspace.exitCode === 0);
  const over = passed.filter((workspace) => measured && workspace.ms >= BUDGET_MS);
  const report = [
    '',
    `test:budget: each workspace alone, under ${seconds(BUDGET_MS)} (load average ${averages(run.load)} before them, on ${run.cores} cores)`,
    ...timed.map((workspace) => `  ${seconds(workspace.ms).padStart(7)}  ${workspace.name}`),
    ...untimed.map(
      (workspace) =>
        `  no time  ${workspace.name}: exit ${workspace.exitCode}, its own summary did not read`,
    ),
    ...notMeasured(run),
  ];
  const failure = [
    ...testsFailed(run.workspaces.filter((workspace) => workspace.exitCode !== 0)),
    ...noTime(untimed),
    ...overBudget(over),
  ];
  if (failure.length > 0) return { report, failure, code: 1 };
  return { report, failure, code: 0 };
}

const notMeasured = (run: Run): ReadonlyArray<string> => {
  if (quiet(run)) return [];
  return [`test:budget: not measured (load average ${averages(run.load)}, on ${run.cores} cores)`];
}

/** The first run of `words` that is `phrase`'s words, by index; none when it is not there. */
const phraseAt = (words: ReadonlyArray<string>, phrase: ReadonlyArray<string>) => {
  for (let i = 0; i + phrase.length <= words.length; i++)
    if (phrase.every((p, k) => words[i + k] === p)) return Option.some(i);
  return Option.none<number>();
}

