    onSome: (raw) => {
      const port = Number(raw);
      return Number.isInteger(port) && port > 0 && port < 65536
        ? Effect.succeed(port)
        : Effect.fail(LabPortInvalid.make({ raw }));
    },
  })

/** Each take's words, read from its transcript files; one that does not read is logged and left out. */
const transcriptsOf = (files: ReadonlyArray<string>) =>
  Effect.forEach(files, (file) =>
    fs.readFileString(file).pipe(
      Effect.flatMap(Schema.decodeUnknownEffect(Schema.fromJsonString(Transcript))),
      Effect.tapError((cause) =>
        Effect.logWarning('takes.transcript.unread').pipe(
          Effect.annotateLogs({ file, cause: String(cause) }),
        ),
      ),
      Effect.option,
    ),
  ).pipe(Effect.map(Arr.getSomes))

/** The beat's mark `name`, in seconds into the scene; refused when the beat has none of that name. */
const markAt = (beat: string, marks: ReadonlyArray<Mark>, name: string) =>
  Effect.fromOption(Arr.findFirst(marks, (m) => m.name === name)).pipe(
    Effect.map((m) => m.at),
    Effect.mapError(() =>
      MarkMissing.make({ beat, name, marks: marks.map((m) => m.name) }),
    ),
  )

/** Writes the mix's track and answers where it is; a write that fails is TrackUnwritten. */
export const writeTrack = Effect.fn('mix.writeTrack')(function* (film: string, pcm: Float32Array) {
  const fs = yield* FileSystem.FileSystem;
  const at = path.join(outDir(film), 'mix.wav');
  yield* fs
    .writeFile(at, encodeWav(pcm))
    .pipe(Effect.mapError((cause) => TrackUnwritten.make({ film, file: at, cause })));
  return { file: at };
})
